const fileName = String($json.name || $json.fileName || '').trim();
const mimeType = String($json.mimeType || '').toLowerCase();
const supportedVideo = /\.(mp4|mov|webm)$/i.test(fileName);
const isVideo = mimeType.startsWith('video/') || supportedVideo;
const topic = fileName.replace(/\.[^.]+$/, '').replace(/[_-]+/g, ' ').trim();
return [{ json: { ...$json, isVideo, topic, fileId: $json.id || $json.fileId, fileName } }];

const ai = $input.first()?.json || {};
const texts = [];
const walk = (v,d=0) => { if(d>8||v==null)return; if(typeof v==='string'){if(v.trim())texts.push(v.trim());return;} if(Array.isArray(v)){v.forEach(x=>walk(x,d+1));return;} if(typeof v==='object')Object.values(v).forEach(x=>walk(x,d+1)); };
walk(ai);
const raw=texts.find(t=>t.includes('{'))||texts.sort((a,b)=>b.length-a.length)[0]||'';
let parsed={}; try{parsed=JSON.parse(raw)}catch{const s=raw.indexOf('{'),e=raw.lastIndexOf('}');if(s>=0&&e>s)try{parsed=JSON.parse(raw.slice(s,e+1))}catch{}}
const trigger=$('Google Drive Trigger - File mới trong folder').first().json;
const youtubeTitle=String(parsed.youtubeTitle||'').trim().slice(0,100);
const youtubeDescription=String(parsed.youtubeDescription||'').trim();
const youtubeContent=String(parsed.youtube||youtubeDescription).trim();
if(!youtubeTitle||!youtubeDescription||!youtubeContent)throw new Error('AI chưa tạo đủ tiêu đề, mô tả hoặc nội dung YouTube.');
return [{json:{sourceRowId:'google-drive-'+String(trigger.id),employeeName:'Google Drive',originalNote:'Video Drive: '+String(trigger.name||'').trim(),postType:'youtube_short',videoFileId:String(trigger.id),videoFileName:String(trigger.name||'video.mp4'),youtubeTitle,youtubeDescription,youtubeContent}}];
